+/* ── 주요 지표 (AT A GLANCE) ────────────────────────────────────────────── */
+
+export type AtAGlance = {
+  per: number;
+  pbr: number;
+  eps: number;
+  bps: number;
+  week52High: number;
+  week52Low: number;
+};
