+  revenueGrowth: number;
+  operatingProfitGrowth: number;
+  netIncomeGrowth: number;
+  marketCap: number;
+  per: number;
+  pbr: number;
+  roe: number;
+  debtRatio: number;
+  operatingProfit: number;
+  netIncome: number;
+  eps: number;
