+function quarterLabels(count: number, endYear: number, endQuarter: number): string[] {
+  const labels: string[] = [];
+  let y = endYear;
+  let q = endQuarter;
+  for (let i = 0; i < count; i++) {
+    labels.unshift(`${y} Q${q}`);
+    q -= 1;
+    if (q === 0) {
+      q = 4;
+      y -= 1;
+    }
+  }
+  return labels;
+}
